export type RetryOptions = {
  maxAttempts: number
  baseDelayMs: number
  shouldRetry: (error: unknown) => boolean
}

export async function retry<T>(
  fn: () => Promise<T>,
  options: RetryOptions,
): Promise<T> {
  let attempt = 0
  while (true) {
    attempt++
    try {
      return await fn()
    } catch (err) {
      if (attempt >= options.maxAttempts) throw err
      if (!options.shouldRetry(err)) throw err
    }
  }
}

